     8→bool FWjWorldWallLayoutConverter::ConvertPlacedObjectsToWallLayout(
     9→	const TArray<FPlacedObjectSaveEntry>& PlacedObjects,
    10→	const FVector& BrickSize,
    11→	TArray<TArray<int32>>& OutWallLayout,
    12→	int32& OutRowNum,
    13→	int32& OutColumnNum,
    14→	FVector& OutCenterOffset)
    15→{
    16→	OutWallLayout.Empty();
    17→	OutRowNum = 0;
    18→	OutColumnNum = 0;
    19→	OutCenterOffset = FVector::ZeroVector;
    20→
    21→	if (PlacedObjects.Num() == 0)
    22→	{
    23→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("WallLayoutConverter: No placed objects to convert"));
    24→		return false;
    25→	}
    26→
    27→	if (BrickSize.X <= 0 || BrickSize.Y <= 0)
    28→	{
    29→		UE_LOG(LogWjWorldPlacement, Error, TEXT("WallLayoutConverter: Invalid BrickSize"));
    30→		return false;
    31→	}
    32→
    33→	// 1. 모든 배치된 오브젝트의 위치에서 그리드 좌표 범위 계산
    34→	int32 MinGridX = MAX_int32, MaxGridX = MIN_int32;
    35→	int32 MinGridY = MAX_int32, MaxGridY = MIN_int32;
    36→
    37→	TArray<FIntPoint> GridPositions;
    38→	GridPositions.Reserve(PlacedObjects.Num());
    39→
    40→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
    41→	{
    42→		const FVector& Location = Entry.Transform.GetLocation();
    43→
    44→		// 월드 좌표 -> 그리드 좌표 변환
    45→		// X축 -> Column, Y축 -> Row로 매핑
    46→		int32 GridX = FMath::RoundToInt(Location.X / BrickSize.X);
    47→		int32 GridY = FMath::RoundToInt(Location.Y / BrickSize.Y);
    48→
    49→		GridPositions.Add(FIntPoint(GridX, GridY));
    50→
    51→		MinGridX = FMath::Min(MinGridX, GridX);
    52→		MaxGridX = FMath::Max(MaxGridX, GridX);
    53→		MinGridY = FMath::Min(MinGridY, GridY);
    54→		MaxGridY = FMath::Max(MaxGridY, GridY);
    55→	}
    56→
    57→	// 2. 그리드 크기 계산 (1칸 여유 공간 추가 - 벽이 둘러싸기 위함)
    58→	const int32 Padding = 1;
    59→	OutColumnNum = (MaxGridX - MinGridX + 1) + (Padding * 2);
    60→	OutRowNum = (MaxGridY - MinGridY + 1) + (Padding * 2);
    61→
    62→	// 3. 빈 그리드 초기화 (-1 = 빈 셀)
    63→	OutWallLayout.SetNum(OutRowNum);
    64→	for (int32 Row = 0; Row < OutRowNum; ++Row)
    65→	{
    66→		OutWallLayout[Row].Init(WallCell_Empty, OutColumnNum);
    67→	}
    68→
    69→	// 4. 배치된 오브젝트 위치에 벽(1) 표시
    70→	for (const FIntPoint& GridPos : GridPositions)
    71→	{
    72→		// 패딩 고려하여 오프셋 적용
    73→		int32 AdjustedCol = (GridPos.X - MinGridX) + Padding;
    74→		int32 AdjustedRow = (GridPos.Y - MinGridY) + Padding;
    75→
    76→		if (OutWallLayout.IsValidIndex(AdjustedRow) && OutWallLayout[AdjustedRow].IsValidIndex(AdjustedCol))
    77→		{
    78→			OutWallLayout[AdjustedRow][AdjustedCol] = WallCell_Wall;
    79→		}
    80→	}
    81→
    82→	// 5. 중심 오프셋 계산 (그리드 원점 -> 월드 좌표)
    83→	OutCenterOffset.X = (MinGridX - Padding) * BrickSize.X;
    84→	OutCenterOffset.Y = (MinGridY - Padding) * BrickSize.Y;
    85→	OutCenterOffset.Z = 0.0f;
    86→
    87→	UE_LOG(LogWjWorldPlacement, Log, TEXT("WallLayoutConverter: Converted %d objects to %dx%d grid"),
    88→		PlacedObjects.Num(), OutRowNum, OutColumnNum);
    89→
    90→	return true;
    91→}
