   437→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportLayoutAsCSV: Only available in ApproachingWall context"));
   438→		return false;
   439→	}
   440→
   441→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   442→	if (!DataProvider)
   443→	{
   444→		UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportLayoutAsCSV: No data provider"));
   445→		return false;
   446→	}
   447→
   448→	const TArray<FPlacedObjectSaveEntry>& PlacedObjects = DataProvider->GetPlacedObjects();
   449→	if (PlacedObjects.Num() == 0)
   450→	{
   451→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportLayoutAsCSV: No objects to export"));
   452→		return false;
   453→	}
   454→
   455→	// 그리드 설정 (기본값 사용, 추후 설정 가능하게 확장 가능)
   456→	const FApproachingWallGridConfig GridConfig;
   457→	const FVector& BrickSize = GridConfig.BrickSize;
   458→
   459→	// 1. 배치된 오브젝트의 바운딩 박스 계산
   460→	FVector MinBounds(FLT_MAX, FLT_MAX, FLT_MAX);
   461→	FVector MaxBounds(-FLT_MAX, -FLT_MAX, -FLT_MAX);
   462→
   463→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   464→	{
   465→		const FVector& Location = Entry.Transform.GetLocation();
   466→		MinBounds.X = FMath::Min(MinBounds.X, Location.X);
   467→		MinBounds.Y = FMath::Min(MinBounds.Y, Location.Y);
   468→		MaxBounds.X = FMath::Max(MaxBounds.X, Location.X);
   469→		MaxBounds.Y = FMath::Max(MaxBounds.Y, Location.Y);
   470→	}
   471→
   472→	// 2. 그리드 크기 계산
   473→	int32 GridColumns = FMath::CeilToInt((MaxBounds.X - MinBounds.X) / BrickSize.X) + 1;
   474→	int32 GridRows = FMath::CeilToInt((MaxBounds.Y - MinBounds.Y) / BrickSize.Y) + 1;
   475→
   476→	// 최소 크기 보장
   477→	GridColumns = FMath::Max(GridColumns, 3);
   478→	GridRows = FMath::Max(GridRows, 3);
   479→
   480→	// 그리드 원점 (좌하단)
   481→	FVector GridOrigin = MinBounds - FVector(BrickSize.X * 0.5f, BrickSize.Y * 0.5f, 0.0f);
   482→
   483→	// 3. 그리드 초기화 (-1 = Empty)
   484→	TArray<TArray<int32>> Grid;
   485→	Grid.SetNum(GridRows);
   486→	for (int32 Row = 0; Row < GridRows; ++Row)
   487→	{
   488→		Grid[Row].SetNum(GridColumns);
   489→		for (int32 Col = 0; Col < GridColumns; ++Col)
   490→		{
   491→			Grid[Row][Col] = -1;
   492→		}
   493→	}
   494→
   495→	// 4. 오브젝트를 그리드에 매핑
   496→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   497→	{
   498→		const FVector& Location = Entry.Transform.GetLocation();
   499→
   500→		// 월드 좌표 → 그리드 인덱스
   501→		int32 Col = FMath::FloorToInt((Location.X - GridOrigin.X) / BrickSize.X);
   502→		int32 Row = FMath::FloorToInt((Location.Y - GridOrigin.Y) / BrickSize.Y);
   503→
   504→		// 범위 체크
   505→		if (Row >= 0 && Row < GridRows && Col >= 0 && Col < GridColumns)
   506→		{
   507→			int32 BrickTypeValue = ObjectIdToBrickTypeValue(Entry.ObjectId);
   508→			Grid[Row][Col] = BrickTypeValue;
   509→		}
   510→	}
   511→
   512→	// 5. CSV 문자열 생성 (첫 줄에 메타데이터 포함)
   513→	FString CSVContent;
   514→
   515→	// ⭐ 메타데이터 헤더: CenterOffset 저장 (클라이언트 프리뷰 위치 동기화용)
   516→	CSVContent += FString::Printf(TEXT("#META:CenterOffset:%f,%f,%f\n"),
   517→		GridOrigin.X, GridOrigin.Y, GridOrigin.Z);
   518→
   519→	for (int32 Row = 0; Row < GridRows; ++Row)
   520→	{
   521→		for (int32 Col = 0; Col < GridColumns; ++Col)
   522→		{
   523→			CSVContent += FString::Printf(TEXT("%d"), Grid[Row][Col]);
   524→			if (Col < GridColumns - 1)
   525→			{
   526→				CSVContent += TEXT(",");
   527→			}
   528→		}
   529→		CSVContent += TEXT("\n");
   530→	}
   531→
   532→	// 6. 파일 저장
   533→	FString UserLayoutDir = GetUserWallLayoutDirectory();
   534→
   535→	// 디렉토리 생성
   536→	IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   537→	if (!PlatformFile.DirectoryExists(*UserLayoutDir))
   538→	{
   539→		PlatformFile.CreateDirectoryTree(*UserLayoutDir);
   540→	}
   541→
   542→	FString FilePath = UserLayoutDir / FileName + TEXT(".csv");
   543→
   544→	if (FFileHelper::SaveStringToFile(CSVContent, *FilePath))
   545→	{
   546→		LastExportedCSVPath = FilePath;
   547→		UE_LOG(LogWjWorldPlacement, Log, TEXT("ExportLayoutAsCSV: Exported to '%s' (Grid: %dx%d)"),
   548→			*FilePath, GridColumns, GridRows);
   549→		return true;
   550→	}
   551→	else
   552→	{
   553→		UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportLayoutAsCSV: Failed to save file '%s'"), *FilePath);
   554→		return false;
   555→	}
   556→}
