   558→void UWjWorldPlacementComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
   559→{
   560→	Super::TickComponent(DeltaTime, TickType, ThisTickFunction);
   561→
   562→	if (CurrentMode == EPlacementMode::Placing && PreviewActor)
   563→	{
   564→		// 프리뷰 위치 갱신
   565→		FHitResult HitResult;
   566→		if (TraceGroundUnderMouse(HitResult))
   567→		{
   568→			const FPlaceableObjectDefinition* Def = Catalog ? Catalog->FindByObjectId(SelectedObjectId) : nullptr;
   569→			float GroundOffset = Def ? Def->GroundOffset : 0.0f;
   570→
   571→			FVector PlaceLocation = HitResult.ImpactPoint + FVector(0.0f, 0.0f, GroundOffset);
   572→
   573→			// AW 컨텍스트: 그리드 스냅 적용
   574→			if (CurrentContext == EPlacementContext::ApproachingWall)
   575→			{
   576→				PlaceLocation = SnapToGrid(PlaceLocation);
   577→			}
   578→
   579→			FRotator PlaceRotation = FRotator(0.0f, PreviewActor->GetCurrentYaw(), 0.0f);
   580→			PreviewActor->UpdatePreviewTransform(PlaceLocation, PlaceRotation);
   581→
   582→			// 유효성 검사
   583→			bCurrentPreviewValid = IsPlacementLocationValid(PlaceLocation);
   584→			PreviewActor->SetPreviewValid(bCurrentPreviewValid);
   585→		}
   586→		else
   587→		{
   588→			bCurrentPreviewValid = false;
   589→			PreviewActor->SetPreviewValid(false);
   590→		}
   591→	}
   592→	else if (CurrentMode == EPlacementMode::Deleting)
   593→	{
   594→		// 삭제 모드: 호버 대상 갱신
   595→		AWjWorldPlacedObjectActor* NewHovered = TraceForPlacedObject();
   596→
   597→		if (NewHovered != HoveredObject)
   598→		{
   599→			if (HoveredObject)
   600→			{
   601→				HoveredObject->SetHighlighted(false);
   602→			}
   603→			HoveredObject = NewHovered;
   604→			if (HoveredObject)
   605→			{
   606→				HoveredObject->SetHighlighted(true);
   607→			}
   608→		}
   609→	}
   610→}
