   612→bool UWjWorldPlacementComponent::TraceGroundUnderMouse(FHitResult& OutHit) const
   613→{
   614→	APlayerController* PC = GetPlayerController();
   615→	if (!PC)
   616→	{
   617→		return false;
   618→	}
   619→
   620→	FVector WorldLocation, WorldDirection;
   621→	if (!PC->DeprojectMousePositionToWorld(WorldLocation, WorldDirection))
   622→	{
   623→		return false;
   624→	}
   625→
   626→	FVector TraceEnd = WorldLocation + WorldDirection * TraceDistance;
   627→
   628→	FCollisionQueryParams QueryParams;
   629→	QueryParams.bTraceComplex = false;
   630→	QueryParams.AddIgnoredActor(GetOwner());
   631→	if (PreviewActor)
   632→	{
   633→		QueryParams.AddIgnoredActor(PreviewActor);
   634→	}
   635→
   636→	return GetWorld()->LineTraceSingleByChannel(OutHit, WorldLocation, TraceEnd, ECC_Visibility, QueryParams);
   637→}
