   639→bool UWjWorldPlacementComponent::IsPlacementLocationValid(const FVector& Location) const
   640→{
   641→	UWorld* World = GetWorld();
   642→	if (!World)
   643→	{
   644→		return false;
   645→	}
   646→
   647→	// AW 컨텍스트: 그리드 스냅 사용 시 더 작은 반경으로 정확히 같은 위치만 체크
   648→	// 일반 컨텍스트: 기존 겹침 반경 사용
   649→	float CheckRadius = (CurrentContext == EPlacementContext::ApproachingWall)
   650→		? GridOverlapCheckRadius
   651→		: OverlapCheckRadius;
   652→
   653→	// 겹침 체크: 기존 배치된 오브젝트와 겹치는지
   654→	TArray<FOverlapResult> Overlaps;
   655→	FCollisionQueryParams QueryParams;
   656→	QueryParams.AddIgnoredActor(GetOwner());
   657→	if (PreviewActor)
   658→	{
   659→		QueryParams.AddIgnoredActor(PreviewActor);
   660→	}
   661→
   662→	FCollisionShape SphereShape = FCollisionShape::MakeSphere(CheckRadius);
   663→	World->OverlapMultiByChannel(Overlaps, Location, FQuat::Identity, ECC_Visibility, SphereShape, QueryParams);
   664→
   665→	for (const FOverlapResult& Overlap : Overlaps)
   666→	{
   667→		if (Cast<AWjWorldPlacedObjectActor>(Overlap.GetActor()))
   668→		{
   669→			return false;
   670→		}
   671→	}
   672→
   673→	return true;
   674→}
   675→
   676→FVector UWjWorldPlacementComponent::SnapToGrid(const FVector& Location) const
   677→{
   678→	// AW 그리드 설정 사용
   679→	const FApproachingWallGridConfig GridConfig;
   680→	const FVector& BrickSize = GridConfig.BrickSize;
   681→
   682→	// 그리드 스냅: 각 축을 BrickSize 단위로 반올림
   683→	FVector SnappedLocation;
   684→	SnappedLocation.X = FMath::RoundToFloat(Location.X / BrickSize.X) * BrickSize.X;
   685→	SnappedLocation.Y = FMath::RoundToFloat(Location.Y / BrickSize.Y) * BrickSize.Y;
   686→	SnappedLocation.Z = Location.Z; // Z축은 스냅하지 않음 (바닥 높이 유지)
   687→
   688→	return SnappedLocation;
   689→}
