   691→AWjWorldPlacedObjectActor* UWjWorldPlacementComponent::TraceForPlacedObject() const
   692→{
   693→	APlayerController* PC = GetPlayerController();
   694→	if (!PC)
   695→	{
   696→		return nullptr;
   697→	}
   698→
   699→	FVector WorldLocation, WorldDirection;
   700→	if (!PC->DeprojectMousePositionToWorld(WorldLocation, WorldDirection))
   701→	{
   702→		return nullptr;
   703→	}
   704→
   705→	FVector TraceEnd = WorldLocation + WorldDirection * TraceDistance;
   706→
   707→	FHitResult HitResult;
   708→	FCollisionQueryParams QueryParams;
   709→	QueryParams.bTraceComplex = false;
   710→	QueryParams.AddIgnoredActor(GetOwner());
   711→
   712→	if (GetWorld()->LineTraceSingleByChannel(HitResult, WorldLocation, TraceEnd, ECC_Visibility, QueryParams))
   713→	{
   714→		return Cast<AWjWorldPlacedObjectActor>(HitResult.GetActor());
   715→	}
   716→
   717→	return nullptr;
   718→}
