   800→void UWjWorldPlacementComponent::BindInputActions()
   801→{
   802→	APlayerController* PC = GetPlayerController();
   803→	if (!PC)
   804→	{
   805→		return;
   806→	}
   807→
   808→	// MappingContext 추가
   809→	if (PlacementMappingContext)
   810→	{
   811→		if (UEnhancedInputLocalPlayerSubsystem* Subsystem = ULocalPlayer::GetSubsystem<UEnhancedInputLocalPlayerSubsystem>(PC->GetLocalPlayer()))
   812→		{
   813→			Subsystem->AddMappingContext(PlacementMappingContext, 1);
   814→		}
   815→	}
   816→
   817→	// InputAction 바인딩
   818→	if (UEnhancedInputComponent* EIC = Cast<UEnhancedInputComponent>(PC->InputComponent))
   819→	{
   820→		if (ConfirmAction)
   821→		{
   822→			EIC->BindAction(ConfirmAction, ETriggerEvent::Triggered, this, &UWjWorldPlacementComponent::OnConfirmAction);
   823→		}
   824→		if (CancelAction)
   825→		{
   826→			EIC->BindAction(CancelAction, ETriggerEvent::Triggered, this, &UWjWorldPlacementComponent::OnCancelAction);
   827→		}
   828→		if (RotateAction)
   829→		{
   830→			EIC->BindAction(RotateAction, ETriggerEvent::Triggered, this, &UWjWorldPlacementComponent::OnRotateAction);
   831→		}
   832→		if (DeleteAction)
   833→		{
   834→			EIC->BindAction(DeleteAction, ETriggerEvent::Triggered, this, &UWjWorldPlacementComponent::OnDeleteAction);
   835→		}
   836→	}
   837→}
