   931→int32 UWjWorldPlacementComponent::FindPlacedObjectIndex(AWjWorldPlacedObjectActor* Actor) const
   932→{
   933→	if (!Actor)
   934→	{
   935→		return INDEX_NONE;
   936→	}
   937→
   938→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   939→	if (!DataProvider)
   940→	{
   941→		return INDEX_NONE;
   942→	}
   943→
   944→	const TArray<FPlacedObjectSaveEntry>& PlacedObjects = DataProvider->GetPlacedObjects();
   945→	FName TargetId = Actor->GetObjectId();
   946→	FVector TargetLocation = Actor->GetActorLocation();
   947→
   948→	// ObjectId와 위치로 매칭 (동일 ObjectId가 여러 개 있을 수 있으므로 위치도 체크)
   949→	for (int32 i = 0; i < PlacedObjects.Num(); ++i)
   950→	{
   951→		const FPlacedObjectSaveEntry& Entry = PlacedObjects[i];
   952→		if (Entry.ObjectId == TargetId)
   953→		{
   954→			// 위치가 가까우면 매치
   955→			if (FVector::DistSquared(Entry.Transform.GetLocation(), TargetLocation) < 100.0f)
   956→			{
   957→				return i;
   958→			}
   959→		}
   960→	}
   961→
   962→	return INDEX_NONE;
   963→}
