   228→#if WITH_STEAM
   229→void UWjWorldStatsSubsystem::OnSteamUserStatsReceivedCallback(UserStatsReceived_t* pCallback, bool bIOFailure)
   230→{
   231→	if (bIOFailure || !pCallback)
   232→	{
   233→		UE_LOG(LogWjWorldStats, Warning, TEXT("StatsSubsystem: User stats request IO failure"));
   234→		return;
   235→	}
   236→
   237→	if (pCallback->m_eResult != k_EResultOK)
   238→	{
   239→		UE_LOG(LogWjWorldStats, Warning, TEXT("StatsSubsystem: User stats request failed (Result=%d)"), pCallback->m_eResult);
   240→		return;
   241→	}
   242→
   243→	uint64 SteamId = pCallback->m_steamIDUser.ConvertToUint64();
   244→	FString UserIdStr = FString::Printf(TEXT("%llu"), SteamId);
   245→	ReadyUserIds.Add(UserIdStr);
   246→
   247→	// Steam OSS를 통해 FUniqueNetIdRepl 생성 (올바른 형식 보장)
   248→	FUniqueNetIdRepl UserIdRepl;
   249→	IOnlineSubsystem* OSS = IOnlineSubsystem::Get(STEAM_SUBSYSTEM);
   250→	if (OSS)
   251→	{
   252→		IOnlineIdentityPtr IdentityInterface = OSS->GetIdentityInterface();
   253→		if (IdentityInterface.IsValid())
   254→		{
   255→			UserIdRepl = FUniqueNetIdRepl(IdentityInterface->CreateUniquePlayerId(UserIdStr));
   256→		}
   257→	}
   258→
   259→	OnUserStatsReceived.Broadcast(UserIdRepl);
   260→	UE_LOG(LogWjWorldStats, Log, TEXT("StatsSubsystem: User stats received for %s, UniqueId valid=%d"),
   261→		*UserIdStr, UserIdRepl.IsValid());
   262→}
   263→#endif
