   269→	FVector SpawnLocation(0.f, 0.f, -10000.f);
   270→	PreviewActor = World->SpawnActor<ACharacterPreviewActor>(ACharacterPreviewActor::StaticClass(), SpawnLocation, FRotator::ZeroRotator, SpawnParams);
