   116→void AWjWorldCharacterPlay::HandleEliminationEffects()
   117→{
   118→	// 움직임 비활성화
   119→	if (UCharacterMovementComponent* MovementComp = GetCharacterMovement())
   120→	{
   121→		MovementComp->DisableMovement();
   122→		MovementComp->StopMovementImmediately();
   123→	}
   124→
   125→	// 입력 비활성화 + 관전 대상 전환 (로컬 컨트롤러에서만)
   126→	APlayerController* PC = Cast<APlayerController>(GetController());
   127→	if (PC)
   128→	{
   129→		DisableInput(PC);
   130→
   131→		if (PC->IsLocalController())
   132→		{
   133→			// 살아있는 다른 플레이어 찾아서 관전
   134→			AGameStateBase* GS = GetWorld()->GetGameState<AGameStateBase>();
   135→			if (GS)
   136→			{
   137→				for (APlayerState* PS : GS->PlayerArray)
   138→				{
   139→					if (!PS || PS == PC->PlayerState) continue;
   140→					APawn* OtherPawn = PS->GetPawn();
   141→					AWjWorldCharacterPlay* OtherChar = Cast<AWjWorldCharacterPlay>(OtherPawn);
   142→					if (OtherChar && !OtherChar->IsEliminated())
   143→					{
   144→						PC->SetViewTargetWithBlend(OtherChar, 0.5f);
   145→						UE_LOG(LogWjWorld, Log, TEXT("HandleEliminationEffects: Spectating %s"), *PS->GetPlayerName());
   146→						break;
   147→					}
   148→				}
   149→			}
   150→		}
   151→	}
   152→
   153→	// 1초 후 캐릭터 파괴
   154→	if (GetWorld())
   155→	{
   156→		FTimerHandle DestroyHandle;
   157→		GetWorld()->GetTimerManager().SetTimer(DestroyHandle, [this]()
   158→		{
   159→			Destroy();
   160→		}, 1.0f, false);
   161→	}
   162→}
