	DOREPLIFETIME(AWjWorldCharacterPlay, bIsEliminated);
	DOREPLIFETIME(AWjWorldCharacterPlay, bIsCarryingBrick);
	DOREPLIFETIME(AWjWorldCharacterPlay, CarriedBrickMesh);
