   305→	if (AlivePlayerCount == 1)
   306→	{
   307→		for (const auto& AlivePlayer : AlivePlayers)
   308→		{
   309→			if (AlivePlayer.IsValid())
   310→			{
   311→				EliminationOrder.Add(AlivePlayer);
