   708→void UWjWorldGameRuleSumo::SpawnPowerUp()
   709→{
   710→	UWorld* World = GetWorld();
   711→	if (!World || !PowerUpActorClass) return;
   712→
   713→	FVector SpawnLoc = GetRandomSpawnLocationOnActiveRings();
   714→	SpawnLoc.Z += 100.f; // ?뚮옯???꾩뿉 ?꾩슦湲?
   715→
   716→	FActorSpawnParameters SpawnParams;
   717→	SpawnParams.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AdjustIfPossibleButAlwaysSpawn;
   718→
   719→	ASumoPowerUpActor* PowerUp = World->SpawnActor<ASumoPowerUpActor>(PowerUpActorClass, SpawnLoc, FRotator::ZeroRotator, SpawnParams);
   720→	if (PowerUp)
   721→	{
   722→		// ?쒕뜡 ????ㅼ젙
   723→		int32 RandType = FMath::RandRange(0, 2);
   724→		PowerUp->SetPowerUpType(static_cast<ESumoPowerUpType>(RandType));
   725→
   726→		ActivePowerUps.Add(PowerUp);
   727→
   728→		UE_LOG(LogWjWorld, Log, TEXT("GameRuleSumo: Spawned PowerUp type %d at %s"), RandType, *SpawnLoc.ToString());
   729→	}
   730→}
