   759→void UWjWorldGameRuleSumo::CleanupPowerUps()
   760→{
   761→	for (const auto& WeakPU : ActivePowerUps)
   762→	{
   763→		if (WeakPU.IsValid())
   764→		{
   765→			WeakPU->Destroy();
   766→		}
   767→	}
   768→	ActivePowerUps.Empty();
   769→}
