    85→void UGA_Push::ExecutePush(const FGameplayAbilityActivationInfo& ActivationInfo)
    86→{
    87→	// 서버에서만 처리
    88→	if (!HasAuthority(&ActivationInfo))
    89→	{
    90→		return;
    91→	}
    92→
    93→	AActor* AvatarActor = GetAvatarActorFromActorInfo();
    94→	if (!AvatarActor) return;
    95→
    96→	AWjWorldCharacterPlay* OwnerCharacter = Cast<AWjWorldCharacterPlay>(AvatarActor);
    97→	if (!OwnerCharacter) return;
    98→
    99→	// SuperPush 버프 체크 (사용 후 제거)
   100→	UAbilitySystemComponent* OwnerASC = GetAbilitySystemComponentFromActorInfo();
   101→	bool bIsSuperPush = false;
   102→	if (OwnerASC && OwnerASC->HasMatchingGameplayTag(WjWorldGameplayTag::Buff_SuperPush()))
   103→	{
   104→		bIsSuperPush = true;
   105→		OwnerASC->RemoveLooseGameplayTag(WjWorldGameplayTag::Buff_SuperPush());
   106→		UE_LOG(LogWjWorldAbilities, Log, TEXT("GA_Push: SuperPush consumed!"));
   107→	}
   108→
   109→	float EffectivePushForce = bIsSuperPush ? PushForce * SuperPushMultiplier : PushForce;
   110→	float EffectiveUpForce = bIsSuperPush ? PushUpForce * SuperPushMultiplier : PushUpForce;
   111→
   112→	FVector Origin = AvatarActor->GetActorLocation();
   113→	FVector ForwardDir = AvatarActor->GetActorForwardVector();
   114→
   115→	// 전방 오버랩 중심 (캐릭터 전방에 약간 오프셋)
   116→	FVector OverlapCenter = Origin + ForwardDir * (PushRange * 0.5f);
   117→
   118→	TArray<FOverlapResult> Overlaps;
   119→	FCollisionShape CollisionShape = FCollisionShape::MakeSphere(PushRange);
   120→
   121→	if (GetWorld()->OverlapMultiByObjectType(
   122→		Overlaps,
   123→		OverlapCenter,
   124→		FQuat::Identity,
   125→		FCollisionObjectQueryParams(ECollisionChannel::ECC_Pawn),
   126→		CollisionShape))
   127→	{
   128→		for (const FOverlapResult& Overlap : Overlaps)
   129→		{
   130→			AWjWorldCharacterPlay* HitCharacter = Cast<AWjWorldCharacterPlay>(Overlap.GetActor());
   131→			if (!HitCharacter || HitCharacter == OwnerCharacter) continue;
   132→			if (HitCharacter->IsEliminated()) continue;
   133→
   134→			// 넉백 방향 계산: 공격자 → 피격자
   135→			FVector PushDir = (HitCharacter->GetActorLocation() - Origin).GetSafeNormal2D();
   136→			if (PushDir.IsNearlyZero())
   137→			{
   138→				PushDir = ForwardDir;
   139→			}
   140→
   141→			FVector LaunchVelocity = PushDir * EffectivePushForce + FVector(0.f, 0.f, EffectiveUpForce);
   142→			HitCharacter->LaunchCharacter(LaunchVelocity, true, true);
   143→
   144→			// 킬 추적용 마지막 공격자 설정
   145→			HitCharacter->SetLastAttacker(OwnerCharacter);
   146→
   147→			// 피격자 카메라 셰이크
   148→			if (PushHitCameraShake)
   149→			{
   150→				APlayerController* HitPC = Cast<APlayerController>(HitCharacter->GetController());
   151→				if (HitPC)
   152→				{
   153→					HitPC->ClientStartCameraShake(PushHitCameraShake);
   154→				}
   155→			}
   156→
   157→			UE_LOG(LogWjWorldAbilities, Log, TEXT("GA_Push: Pushed %s with force (%s)%s"),
   158→				*HitCharacter->GetName(), *LaunchVelocity.ToString(),
   159→				bIsSuperPush ? TEXT(" [SUPER]") : TEXT(""));
   160→		}
   161→	}
   162→}
