    31→	Mesh = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("Mesh"));
    32→	Mesh->SetupAttachment(RootComponent);
    33→	Mesh->SetCollisionEnabled(ECollisionEnabled::NoCollision);
    34→	Mesh->SetRelativeScale3D(FVector(0.5f));
    35→
    36→	// Rotating
    37→	RotatingMovement = CreateDefaultSubobject<URotatingMovementComponent>(TEXT("RotatingMovement"));
    38→	RotatingMovement->RotationRate = FRotator(0.f, 90.f, 0.f);
