    72→void ASumoPowerUpActor::ApplyMeshForType()
    73→{
    74→	if (!Mesh) return;
    75→
    76→	UStaticMesh* TargetMesh = nullptr;
    77→
    78→	switch (PowerUpType)
    79→	{
    80→	case ESumoPowerUpType::SpeedBoost:
    81→		TargetMesh = SpeedBoostMesh;
    82→		break;
    83→	case ESumoPowerUpType::SuperPush:
    84→		TargetMesh = SuperPushMesh;
    85→		break;
    86→	case ESumoPowerUpType::Shield:
    87→		TargetMesh = ShieldMesh;
    88→		break;
    89→	}
    90→
    91→	if (TargetMesh)
    92→	{
    93→		Mesh->SetStaticMesh(TargetMesh);
    94→	}
    95→}
