    97→void ASumoPowerUpActor::OnOverlapBegin(UPrimitiveComponent* OverlappedComponent, AActor* OtherActor,
    98→	UPrimitiveComponent* OtherComp, int32 OtherBodyIndex, bool bFromSweep, const FHitResult& SweepResult)
    99→{
   100→	if (!HasAuthority()) return;
   101→
   102→	AWjWorldCharacterPlay* Character = Cast<AWjWorldCharacterPlay>(OtherActor);
   103→	if (!Character || Character->IsEliminated()) return;
   104→
   105→	ApplyPowerUp(Character);
   106→	Destroy();
   107→}
   108→
   109→void ASumoPowerUpActor::ApplyPowerUp(AWjWorldCharacterPlay* Character)
   110→{
   111→	if (!Character) return;
   112→
   113→	UAbilitySystemComponent* ASC = Character->GetAbilitySystemComponent();
   114→	if (!ASC) return;
   115→
   116→	switch (PowerUpType)
   117→	{
   118→	case ESumoPowerUpType::SpeedBoost:
   119→	{
   120→		// 기존 SpeedBoost 타이머가 있으면 취소하고 속도 먼저 복원
   121→		UCharacterMovementComponent* MovementComp = Character->GetCharacterMovement();
   122→		TWeakObjectPtr<AWjWorldCharacterPlay> WeakChar = Character;
   123→
   124→		if (FTimerHandle* ExistingHandle = SpeedBoostTimerHandles.Find(WeakChar))
   125→		{
   126→			if (ExistingHandle->IsValid())
   127→			{
   128→				GetWorld()->GetTimerManager().ClearTimer(*ExistingHandle);
   129→			}
   130→			SpeedBoostTimerHandles.Remove(WeakChar);
   131→		}
   132→
   133→		ASC->AddLooseGameplayTag(WjWorldGameplayTag::Buff_SpeedBoost());
   134→
   135→		// 이동속도 직접 수정
   136→		if (MovementComp)
   137→		{
   138→			// 이미 버프가 적용된 상태가 아니라면 원래 속도에서 배율 적용
   139→			// (태그로 확인하므로 기존 타이머 취소 후에도 속도가 이미 빨라진 상태일 수 있음)
   140→			float BaseSpeed = MovementComp->MaxWalkSpeed;
   141→			if (!ASC->HasMatchingGameplayTag(WjWorldGameplayTag::Buff_SpeedBoost()))
   142→			{
   143→				// 태그가 방금 추가되었으므로 이 경우는 해당 안됨, 하지만 안전을 위해 체크
   144→				BaseSpeed = MovementComp->MaxWalkSpeed;
   145→			}
   146→			MovementComp->MaxWalkSpeed = BaseSpeed * SpeedBoostMultiplier;
   147→
   148→			float RestoreSpeed = BaseSpeed;
   149→
   150→			// 지속 시간 후 복원
   151→			FTimerHandle SpeedTimerHandle;
   152→			GetWorld()->GetTimerManager().SetTimer(SpeedTimerHandle, FTimerDelegate::CreateLambda(
   153→				[WeakChar, RestoreSpeed]()
   154→				{
   155→					if (AWjWorldCharacterPlay* Char = WeakChar.Get())
   156→					{
   157→						if (UCharacterMovementComponent* MC = Char->GetCharacterMovement())
   158→						{
   159→							MC->MaxWalkSpeed = RestoreSpeed;
   160→						}
   161→						if (UAbilitySystemComponent* CharASC = Char->GetAbilitySystemComponent())
   162→						{
   163→							CharASC->RemoveLooseGameplayTag(WjWorldGameplayTag::Buff_SpeedBoost());
   164→						}
   165→					}
   166→					// 타이머 완료 후 맵에서 제거
   167→					SpeedBoostTimerHandles.Remove(WeakChar);
   168→				}), SpeedBoostDuration, false);
   169→
   170→			// 타이머 핸들 저장
   171→			SpeedBoostTimerHandles.Add(WeakChar, SpeedTimerHandle);
   172→		}
   173→
   174→		UE_LOG(LogWjWorld, Log, TEXT("SumoPowerUp: SpeedBoost applied to %s (%.1fs)"),
   175→			*Character->GetName(), SpeedBoostDuration);
   176→		break;
   177→	}
   178→
   179→	case ESumoPowerUpType::SuperPush:
   180→	{
   181→		ASC->AddLooseGameplayTag(WjWorldGameplayTag::Buff_SuperPush());
   182→		UE_LOG(LogWjWorld, Log, TEXT("SumoPowerUp: SuperPush applied to %s"), *Character->GetName());
   183→		break;
   184→	}
   185→
   186→	case ESumoPowerUpType::Shield:
   187→	{
   188→		ASC->AddLooseGameplayTag(WjWorldGameplayTag::Buff_Shield());
   189→		UE_LOG(LogWjWorld, Log, TEXT("SumoPowerUp: Shield applied to %s"), *Character->GetName());
   190→		break;
   191→	}
   192→	}
   193→
   194→	// GameplayCue 실행
   195→	FGameplayCueParameters CueParams;
   196→	CueParams.Location = Character->GetActorLocation();
   197→	ASC->ExecuteGameplayCue(WjWorldGameplayTag::GameplayCue_Sumo_PowerUp_Pickup(), CueParams);
   198→}
