    50→template<typename T>
    51→inline const T* UWjWorldGameDataComponent::GetValue(const FGameplayTag& InTag) const
    52→{
    53→	if constexpr (std::is_same_v<T, int32>)
    54→	{
    55→		if (IntDataMap.Contains(InTag))
    56→		{
    57→			return &IntDataMap[InTag];
    58→		}
    59→	}
    60→	else if constexpr (std::is_same_v<T, float>)
    61→	{
    62→		if (FloatDataMap.Contains(InTag))
    63→		{
    64→			return &FloatDataMap[InTag];
    65→		}
    66→	}
    67→	else if constexpr (std::is_same_v<T, FString>)
    68→	{
    69→		if (StringDataMap.Contains(InTag))
    70→		{
    71→			return &StringDataMap[InTag];
    72→		}
    73→	}
    74→
    75→	return nullptr;
    76→}
    77→
    78→template<typename T>
    79→inline void UWjWorldGameDataComponent::SetValue(const FGameplayTag& InTag, const T& InValue)
    80→{
    81→	if constexpr (std::is_same_v<T, int32>)
    82→	{
    83→		IntDataMap.Add(InTag, InValue);
    84→	}
    85→	else if constexpr (std::is_same_v<T, float>)
    86→	{
    87→		FloatDataMap.Add(InTag, InValue);
    88→	}
    89→	else if constexpr (std::is_same_v<T, FString>)
    90→	{
    91→		StringDataMap.Add(InTag, InValue);
    92→	}
    93→}
    94→
    95→template<typename T>
    96→inline void UWjWorldGameDataComponent::RemoveValue(const FGameplayTag& InTag)
    97→{
    98→	if constexpr (std::is_same_v<T, int32>)
    99→	{
   100→		IntDataMap.Remove(InTag);
   101→	}
   102→	else if constexpr (std::is_same_v<T, float>)
   103→	{
   104→		FloatDataMap.Remove(InTag);
   105→	}
   106→	else if constexpr (std::is_same_v<T, FString>)
   107→	{
   108→		StringDataMap.Remove(InTag);
   109→	}
   110→}
