   169→void UWjWorldGameRuleSumo::OnPlayerLeft(AWjWorldPlayerStatePlay* Player)
   170→{
   171→	Super::OnPlayerLeft(Player);
   172→
   173→	if (!HasAuthority() || !Player) return;
   174→
   175→	// 罹먮┃???쒓굅 泥섎━
   176→	APawn* PlayerPawn = Player->GetPawn();
   177→	AWjWorldCharacterPlay* PlayerCharacter = Cast<AWjWorldCharacterPlay>(PlayerPawn);
   178→	if (PlayerCharacter && !PlayerCharacter->IsEliminated())
   179→	{
   180→		PlayerCharacter->OnEliminated();
   181→	}
   182→
   183→	if (AlivePlayers.Remove(Player) > 0)
   184→	{
   185→		AlivePlayerCount--;
   186→	}
   187→	AllPlayers.Remove(Player);
   188→	TotalPlayerCount--;
   189→
   190→	UpdateGameData();
   191→
   192→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleSumo: Player Left - %s, Alive: %d, Total: %d"),
   193→		*Player->GetPlayerName(), AlivePlayerCount, TotalPlayerCount);
   194→
   195→	// 紐⑤뱺 ?뚮젅?댁뼱 ?댄깉
   196→	if (TotalPlayerCount <= 0)
   197→	{
   198→		bGameOverConditionMet = true;
   199→		WinnerPlayer = nullptr;
   200→		OnGameEnd();
   201→		return;
   202→	}
   203→
   204→	// ?쇱슫???밸━ 議곌굔 泥댄겕
   205→	if (bIsGameStarted && bIsRoundActive && AlivePlayerCount <= 1)
   206→	{
   207→		OnRoundEnd();
   208→	}
   209→}
