    19→AWjWorldGameModePlay::AWjWorldGameModePlay()
    20→{
    21→	PrimaryActorTick.bCanEverTick = true;
    22→	PrimaryActorTick.bStartWithTickEnabled = true;
    23→
    24→	PlayerStateClass = AWjWorldPlayerStatePlay::StaticClass();
    25→	PlayerControllerClass = AWjWorldPlayerControllerPlay::StaticClass();
    26→	HUDClass = AWjWorldHUDPlay::StaticClass();
    27→	GameStateClass = AWjWorldGameStatePlay::StaticClass();
    28→	DefaultPawnClass = AWjWorldCharacterPlay::StaticClass();
    29→}
    30→
    31→void AWjWorldGameModePlay::InitGame(const FString& MapName, const FString& Options, FString& ErrorMessage)
    32→{
    33→	Super::InitGame(MapName, Options, ErrorMessage);
    34→
    35→	// URL Options에서 GameModeId, MapOption 파싱
    36→	GameModeId = UGameplayStatics::ParseOption(Options, TEXT("GameModeId"));
    37→	MapOption = UGameplayStatics::ParseOption(Options, TEXT("MapOption"));
    38→	UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: GameModeId='%s', MapOption='%s'"), *GameModeId, *MapOption);
    39→
    40→	// 카탈로그에서 GameRuleClass 조회
    41→	TSubclassOf<UWjWorldGameRuleBase> ResolvedGameRuleClass = nullptr;
    42→
    43→	const UWjWorldDeveloperSettings* DevSettings = GetDefault<UWjWorldDeveloperSettings>();
    44→	if (DevSettings && !DevSettings->MinigameCatalog.IsNull())
    45→	{
    46→		UWjWorldMinigameDataAsset* Catalog = DevSettings->MinigameCatalog.LoadSynchronous();
    47→		if (Catalog && !GameModeId.IsEmpty())
    48→		{
    49→			const FWjWorldMinigameDefinition* Def = Catalog->FindByGameModeId(FName(*GameModeId));
    50→			if (Def && Def->GameRuleClass)
    51→			{
    52→				ResolvedGameRuleClass = Def->GameRuleClass;
    53→				UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: GameRuleClass resolved from catalog - %s"),
    54→					*ResolvedGameRuleClass->GetName());
    55→			}
    56→		}
    57→	}
    58→
    59→	// 카탈로그에서 못 찾으면 폴백 (Deprecated)
    60→	if (!ResolvedGameRuleClass && GameRuleClass)
    61→	{
    62→		ResolvedGameRuleClass = GameRuleClass;
    63→		UE_LOG(LogWjWorld, Warning, TEXT("GameModePlay: Using fallback GameRuleClass (deprecated) - %s"),
    64→			*ResolvedGameRuleClass->GetName());
    65→	}
    66→
    67→	// GameRule 생성
    68→	if (ResolvedGameRuleClass)
    69→	{
    70→		CurrentGameRule = NewObject<UWjWorldGameRuleBase>(this, ResolvedGameRuleClass);
    71→		CurrentGameRule->Initialize(this);
    72→	}
    73→	else
    74→	{
    75→		UE_LOG(LogWjWorld, Error, TEXT("GameModePlay: No GameRuleClass found!"));
    76→	}
    77→
    78→	UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: InitGame completed"));
    79→}
    80→
    81→void AWjWorldGameModePlay::StartPlay()
    82→{
    83→	Super::StartPlay();
    84→
    85→	if (CurrentGameRule)
    86→	{
    87→		CurrentGameRule->OnGameReady();
    88→	}
    89→
    90→	UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: StartPlay completed"));
    91→}
    92→
    93→void AWjWorldGameModePlay::Tick(float DeltaSeconds)
    94→{
    95→	Super::Tick(DeltaSeconds);
    96→
    97→	// GameRule 틱 호출
    98→	if (CurrentGameRule)
    99→	{
   100→		CurrentGameRule->TickGameRule(DeltaSeconds);
   101→	}
   102→}
   103→
   104→void AWjWorldGameModePlay::PostLogin(APlayerController* NewPlayer)
   105→{
   106→	Super::PostLogin(NewPlayer);
   107→
   108→	if (CurrentGameRule)
   109→	{
   110→		AWjWorldPlayerStatePlay* NewPlayerState = Cast<AWjWorldPlayerStatePlay>(NewPlayer->PlayerState);
   111→		if (NewPlayerState)
   112→		{
   113→			CurrentGameRule->OnPlayerJoined(NewPlayerState);
   114→		}
   115→	}
   116→
   117→	// Play 중 플레이어 목록 캐시 (호스트 마이그레이션용)
   118→	if (UWjWorldGameInstance* GI = Cast<UWjWorldGameInstance>(GetGameInstance()))
   119→	{
   120→		AGameStateBase* GS = GetGameState<AGameStateBase>();
   121→		if (GS)
   122→		{
   123→			TArray<FPlayerDisplayInfo> PlayerList;
   124→			bool bFirstPlayer = true;
   125→			for (APlayerState* PS : GS->PlayerArray)
   126→			{
   127→				if (PS && !PS->GetPlayerName().IsEmpty())
   128→				{
   129→					FPlayerDisplayInfo Info;
   130→					Info.PlayerName = PS->GetPlayerName();
   131→					Info.PlayerID = PS->GetPlayerId();
   132→					Info.bIsHost = bFirstPlayer; // 서버의 첫 번째 플레이어 = 호스트
   133→					Info.bIsReady = true;
   134→					PlayerList.Add(Info);
   135→					bFirstPlayer = false;
   136→				}
   137→			}
   138→			GI->CachePlayerList(PlayerList);
   139→		}
   140→	}
   141→
   142→	UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: PostLogin completed for %s"), *NewPlayer->GetName());
   143→}
   144→
   145→void AWjWorldGameModePlay::Logout(AController* Exiting)
   146→{
   147→	// GameRule에 플레이어 이탈 알림 (Super::Logout 전에 호출해야 PlayerState가 유효함)
   148→	if (CurrentGameRule && Exiting)
   149→	{
   150→		AWjWorldPlayerStatePlay* ExitingPlayerState = Cast<AWjWorldPlayerStatePlay>(Exiting->PlayerState);
   151→		if (ExitingPlayerState)
   152→		{
   153→			UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: Logout - Notifying GameRule for player %s"), *ExitingPlayerState->GetPlayerName());
   154→			CurrentGameRule->OnPlayerLeft(ExitingPlayerState);
   155→		}
   156→	}
   157→
   158→	Super::Logout(Exiting);
   159→
   160→	UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: Logout completed for %s"), Exiting ? *Exiting->GetName() : TEXT("Unknown"));
   161→}
   162→
   163→void AWjWorldGameModePlay::StartGame(float SecondsForStartCount)
   164→{
   165→	GetGameState<AWjWorldGameStatePlay>()->GameStartWithCountdown(SecondsForStartCount);
   166→	GetGameState<AWjWorldGameStatePlay>()->SetGameRuleClass(CurrentGameRule->GetClass());
   167→
   168→	if(GetWorld() && CurrentGameRule)
   169→	{
   170→		GetWorld()->GetTimerManager().SetTimer(StartGameHandle, FTimerDelegate::CreateLambda([this, SecondsForStartCount]()
   171→		{
   172→			CurrentGameRule->OnGameStart();
   173→			OnGameStart.Broadcast();
   174→		}), SecondsForStartCount, false);
   175→	}
   176→
   177→	UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: StartGame scheduled in %f seconds"), SecondsForStartCount);
   178→}
   179→
   180→void AWjWorldGameModePlay::EndGamePredict(float SecondsForEndCount)
   181→{
   182→	GetGameState<AWjWorldGameStatePlay>()->GameEndWithCountdown(SecondsForEndCount);
   183→	UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: EndGame scheduled in %f seconds"), SecondsForEndCount);
   184→}
   185→
   186→void AWjWorldGameModePlay::OnGameLevelUp(int32 NewLevel)
   187→{
   188→	OnGameLevelChange.Broadcast(NewLevel);
   189→	UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: Game Level Up to %d"), NewLevel);
   190→}
   191→
   192→void AWjWorldGameModePlay::BeginDestroy()
   193→{
   194→	Super::BeginDestroy();
   195→
   196→	UWorld* World = GetWorld();
   197→	if (World)
   198→	{
   199→		World->GetTimerManager().ClearTimer(StartGameHandle);
   200→	}
   201→}

