	UPROPERTY(EditDefaultsOnly, Category = "Cooldown")
	FGameplayTagContainer CooldownTags;

private:
	// GetCooldownTags() 반환용 (부모 태그 + CooldownTags 합산)
	mutable FGameplayTagContainer MergedCooldownTags;
};

